import Proton from './upstream/src/index.js';
(()=>{let canvas,context,proton,renderer,emitter,attractionBehaviour,crossZoneBehaviour;
let stopped=false,raf=0,down=false;const off=[];let media;
const root=document.getElementById('surface');
function on(t,n,f){t.addEventListener(n,f);off.push(()=>t.removeEventListener(n,f))}
function cancel(){if(raf)cancelAnimationFrame(raf);raf=0}
function dispose(){if(stopped)return;stopped=true;cancel();for(const f of off.splice(0))f();down=false;try{proton?.destroy(false)}catch{}proton=null;if(root)root.replaceChildren();}
function fail(){dispose();const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='此设备无法绘制原粒子场。';(root||document.body).append(p)}
function frame(){raf=0;if(stopped||document.hidden)return;try{proton.update();if(!media.matches&&canvas.width&&canvas.height)raf=requestAnimationFrame(frame)}catch{fail()}}
function resume(){cancel();if(stopped||document.hidden)return;proton.then=0;if(canvas.width&&canvas.height)frame()}
function release(){if(stopped||!proton)return;down=false;attractionBehaviour.reset({x:1003/2,y:610/2},0,200)}
function resize(){if(stopped)return;try{canvas.width=Math.min(1800,Math.max(0,window.innerWidth));canvas.height=Math.min(1200,Math.max(0,window.innerHeight));crossZoneBehaviour.reset(new Proton.RectZone(0,0,canvas.width,canvas.height),'cross');resume()}catch{fail()}}
try{if(!root)throw Error('missing root');canvas=document.createElement('canvas');canvas.setAttribute('aria-label','原十六引力井粒子轨迹；按住拖动改变吸引点');root.append(canvas);canvas.width=Math.min(1800,Math.max(0,window.innerWidth));canvas.height=Math.min(1200,Math.max(0,window.innerHeight));context=canvas.getContext('2d');if(!context)throw Error('Canvas2D unavailable');media=matchMedia('(prefers-reduced-motion: reduce)');createProton();
on(canvas,'pointerdown',e=>{if(!stopped)down=true});on(canvas,'pointermove',e=>{if(stopped||!down||!proton)return;try{const b=canvas.getBoundingClientRect();attractionBehaviour.reset({x:e.clientX-b.left,y:e.clientY-b.top},10,500)}catch{fail()}});
on(window,'pointerup',release);on(window,'pointercancel',release);on(window,'blur',release);on(window,'resize',resize);on(document,'visibilitychange',()=>{release();resume()});on(media,'change',resume);on(window,'pagehide',dispose);on(window,'atlas:dispose',dispose);resume();
}catch{fail()}
        function createProton() {
            proton = new Proton;
            emitter = new Proton.Emitter();
            emitter.damping = 0.008;

            emitter.rate = new Proton.Rate(300);
            emitter.addInitialize(new Proton.Mass(1));
            emitter.addInitialize(new Proton.Radius(4));
            emitter.addInitialize(new Proton.Velocity(new Proton.Span(5), new Proton.Span(0, 360), 'polar'));

            attractionBehaviour = new Proton.Attraction({
                x: 1003 / 2,
                y: 610 / 2
            }, 0, 200);

            addAttractionBehaviours();
            crossZoneBehaviour = new Proton.CrossZone(new Proton.RectZone(0, 0, canvas.width, canvas.height), 'bound');
            emitter.addBehaviour(new Proton.Color('random'));
            emitter.addBehaviour(attractionBehaviour);
            emitter.addBehaviour(crossZoneBehaviour);

            emitter.p.x = canvas.width / 2;
            emitter.p.y = canvas.height / 2;
            emitter.emit('once');
            proton.addEmitter(emitter);
            proton.addRenderer(createRenderer());
        }

        function addAttractionBehaviours() {
            var total = 16;
            var d = 360 / total;
            var R = 230;
            for (var i = 0; i < 360; i += d) {
                var x = R * Math.cos(i * Math.PI / 180);
                var y = R * Math.sin(i * Math.PI / 180);
                emitter.addBehaviour(new Proton.GravityWell({
                    x: x + canvas.width / 2,
                    y: y + canvas.height / 2
                }, 5000, 200));
            }

            emitter.addBehaviour(new Proton.Repulsion({
                x: canvas.width / 2,
                y: canvas.height / 2
            }, 5, 200));
        }

        function createRenderer() {
            var renderer = new Proton.CustomRenderer();
            renderer.onProtonUpdate = function() {
                context.fillStyle = "rgba(0, 0, 0, 0.05)";
                context.fillRect(0, 0, canvas.width, canvas.height);
            };

            renderer.onParticleCreated = function(particle) {
                particle.lineWidth = 1;
                particle.tha = Math.random() * Math.PI;
            };

            renderer.onParticleUpdate = function(particle) {
                particle.tha += 0.01;
                particle.lineWidth = Math.abs(Math.sin(particle.tha)) * 2 + 0.1;
                context.beginPath();
                context.strokeStyle = particle.color;
                context.lineWidth = particle.lineWidth;
                context.moveTo(particle.old.p.x, particle.old.p.y);
                context.lineTo(particle.p.x, particle.p.y);
                context.closePath();
                context.stroke();
            };

            return renderer;
        }

})();
